package com.insight.quantlife.tests;
import android.app.*;import android.app.job.*;import android.content.*;import android.database.Cursor;import android.database.sqlite.*;import android.os.*;import com.insight.quantlife.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Disposable emulator only: real SQLite and JobScheduler, model responses on local loopback. */
public final class WikiClassificationTest extends DocumentEditorTest {
 JSONObject row(String id,String title,String note,long version)throws Exception{return new JSONObject().put("id",id).put("type","learning").put("date","2099-01-01").put("title",title).put("platform","测试").put("contentType","article").put("note",note).put("durationMinutes",35).put("tags",new JSONArray()).put("updatedAt",version);}
 void put(SQLiteDatabase db,JSONObject r)throws Exception{ContentValues v=new ContentValues();v.put("id",r.getString("id"));v.put("payload",r.toString());db.insertWithOnConflict("records",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
 JSONObject get(SQLiteDatabase db,String id)throws Exception{try(Cursor c=db.rawQuery("SELECT payload FROM records WHERE id=?",new String[]{id})){return c.moveToFirst()?new JSONObject(c.getString(0)):null;}}
 JSONObject reply(String id,String domain)throws Exception{return new JSONObject().put("text",new JSONObject().put("recordId",id).put("topics",new JSONArray().put("真实主题")).put("domains",new JSONArray().put(domain)).toString());}
 void databaseChecks()throws Exception{
  try(SQLiteDatabase db=SQLiteDatabase.create(null)){
   db.execSQL("CREATE TABLE records(id TEXT PRIMARY KEY,payload TEXT NOT NULL)");db.execSQL("CREATE TABLE wiki_queue(id TEXT PRIMARY KEY,version INTEGER NOT NULL,operation TEXT NOT NULL)");
   StringBuilder text=new StringBuilder();for(int i=0;i<13000;i++)text.append("数据治理");text.append("尾部观点");
   JSONObject r=row("long","详解数据标签体系",text.toString(),8);put(db,r);StringBuilder read=new StringBuilder();int[] calls={0};boolean done=false;
   while(!done){done=WikiClassificationService.step(db,r,p->{calls[0]++;JSONObject input=new JSONObject(p.getJSONArray("messages").getJSONObject(1).getString("content"));read.append(input.getString("note"));return reply("long","商业与管理");});}
   JSONObject saved=get(db,"long");check(read.toString().equals(text.toString())&&calls[0]>2,"Classification reads every chunk through the final characters");check(saved.getJSONArray("wikiDomains").getString(0).equals("商业与管理")&&!WikiClassificationService.needs(saved),"Classification completes independently of Wiki page compilation");check(saved.getString("note").equals(r.getString("note"))&&saved.getDouble("durationMinutes")==35&&saved.getLong("updatedAt")==8&&saved.getJSONArray("tags").length()==0,"Classification only changes derived metadata, never notes, hours, tags or version");
   Class<?> automation=Class.forName("com.insight.quantlife.WikiAutomation");java.lang.reflect.Method queue=automation.getDeclaredMethod("queue",SQLiteDatabase.class,android.content.Context.class),ack=automation.getDeclaredMethod("acknowledge",SQLiteDatabase.class,JSONArray.class),assign=automation.getDeclaredMethod("assign",SQLiteDatabase.class,JSONArray.class);queue.setAccessible(true);ack.setAccessible(true);assign.setAccessible(true);JSONArray oldJobs=((JSONObject)queue.invoke(null,db,getTargetContext())).getJSONArray("jobs");assign.invoke(null,db,new JSONArray().put(new JSONObject().put("id","long").put("version",8).put("topics",new JSONArray().put("新知识主题")).put("domains",new JSONArray().put("AI 与技术"))));check(((Integer)ack.invoke(null,db,oldJobs))==0,"Old compilation acknowledgement cannot discard a newer classification job");check(((Integer)ack.invoke(null,db,((JSONObject)queue.invoke(null,db,getTargetContext())).getJSONArray("jobs")))==1,"Current classification acknowledgement removes only its own queue entry");
   JSONObject changed=row("changed","学习","原文",9);put(db,changed);boolean applied=WikiClassificationService.step(db,changed,p->{put(db,row("changed","新标题","用户新版本",10));return reply("changed","AI 与技术");});check(!applied&&get(db,"changed").getString("note").equals("用户新版本")&&!get(db,"changed").has("wikiDomains"),"In-flight stale response cannot overwrite a concurrent edit");
   JSONObject failed=row("failure","学习","不得清除",10);put(db,failed);boolean invalid=false;try{WikiClassificationService.step(db,failed,p->reply("failure","伪造分类"));}catch(Exception expected){invalid=true;}check(invalid&&!get(db,"failure").has("wikiDomains")&&WikiClassificationService.needs(get(db,"failure")),"Invalid model response leaves work pending and source intact");WikiClassificationService.step(db,failed,p->reply("failure","人文与阅读"));check(!WikiClassificationService.needs(get(db,"failure")),"Retry completes a previously failed source");
   JSONObject other=row("other","不明","上下文不足",10).put("wikiClassificationVersion",3).put("wikiDomainVersion",10).put("wikiTopicVersion",10).put("wikiDomains",new JSONArray().put("其他主题")).put("wikiTopics",new JSONArray().put("未知内容"));check(WikiClassificationService.needs(other),"Old other-topic classifications are re-evaluated after upgrade");put(db,other);WikiClassificationService.step(db,other,p->reply("other","其他主题"));check(!WikiClassificationService.needs(get(db,"other")),"Genuine other-topic classification is retained without a forced percentage");
  }
 }
 volatile boolean serverRunning=true;volatile int networkCalls;ServerSocket server;
 void serve()throws Exception{
  server=new ServerSocket(0,20,InetAddress.getByName("127.0.0.1"));
  new Thread(()->{while(serverRunning)try(Socket socket=server.accept()){
   socket.setSoTimeout(6000);InputStream in=socket.getInputStream();ByteArrayOutputStream header=new ByteArrayOutputStream();int ch;String head="";
   while((ch=in.read())!=-1){header.write(ch);head=header.toString("ISO-8859-1");if(head.endsWith("\r\n\r\n"))break;if(header.size()>32768)throw new IOException();}
   int length=0;for(String line:head.split("\r\n"))if(line.toLowerCase(Locale.ROOT).startsWith("content-length:"))length=Integer.parseInt(line.substring(15).trim());byte[] body=new byte[length];int offset=0;while(offset<length){int n=in.read(body,offset,length-offset);if(n<0)throw new IOException();offset+=n;}
   JSONObject request=new JSONObject(new String(body,StandardCharsets.UTF_8)),input=new JSONObject(request.getJSONArray("messages").getJSONObject(1).getString("content"));String title=input.optString("title"),domain=title.contains("发球")?"健康与生活":title.contains("PyAutoGUI")?"AI 与技术":title.contains("创业")?"商业与管理":"人文与阅读";
   String args=reply(input.getString("recordId"),domain).getString("text");JSONObject function=new JSONObject().put("name","classify_knowledge").put("arguments",args);
   JSONObject message=new JSONObject().put("role","assistant").put("tool_calls",new JSONArray().put(new JSONObject().put("id","call-qa").put("type","function").put("function",function)));
   byte[] response=new JSONObject().put("choices",new JSONArray().put(new JSONObject().put("finish_reason","tool_calls").put("message",message))).toString().getBytes(StandardCharsets.UTF_8);OutputStream out=socket.getOutputStream();out.write(("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: "+response.length+"\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));out.write(response);out.flush();networkCalls++;
  }catch(Exception ignored){} },"local-classifier-model").start();
 }
 @Override public void onStart(){Bundle out=new Bundle();String encrypted=null;SharedPreferences secure=null;try{
  if(!Build.HARDWARE.matches("ranchu|goldfish"))throw new Exception("Disposable emulator required");databaseChecks();h=new MainHost(this);h.open();h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{}");
  secure=getTargetContext().getSharedPreferences("secure",0);encrypted=secure.getString("settings",null);serve();
  for(String[] item:new String[][]{{"000-classify-business","米哈游刘伟回顾创业经历"},{"000-classify-code","PyAutoGUI自动化操作库"},{"000-classify-sport","发球的基本要领与技巧"}})h.call("saveRecord",new JSONObject().put("record",row(item[0],item[1],"阅读上述主题，记录理解与实践。",1)).put("allowDuplicate",true));
  h.call("saveSettings",new JSONObject().put("settings",new JSONObject().put("profile",new JSONObject().put("id","custom").put("baseUrl","http://127.0.0.1:"+server.getLocalPort()+"/v1").put("model","local-synthetic").put("apiKey","local-synthetic-key").put("protocol","chat").put("effort","off"))));
  runOnMainSync(()->h.activity.finish());Thread.sleep(500);h=null; // No Activity or WebView exists while classification runs.
  JobScheduler scheduler=getTargetContext().getSystemService(JobScheduler.class);check(scheduler.getPendingJob(7304)!=null||networkCalls>=3,"Persisted network-constrained classification job survives Activity exit");
  try(android.os.ParcelFileDescriptor shell=getUiAutomation().executeShellCommand("cmd jobscheduler run -f com.insight.quantlife 7304")){byte[] sink=new byte[1024];try(java.io.FileInputStream in=new java.io.FileInputStream(shell.getFileDescriptor())){while(in.read(sink)!=-1){}}}
  boolean done=false;for(int n=0;n<150;n++){try(SQLiteDatabase db=SQLiteDatabase.openDatabase(getTargetContext().getDatabasePath("quantlife.db").getPath(),null,SQLiteDatabase.OPEN_READWRITE)){JSONObject r=get(db,"000-classify-sport");done=r!=null&&!WikiClassificationService.needs(r);}if(done)break;Thread.sleep(200);}
  check(done&&networkCalls>=3,"Actual JobService calls the configured local endpoint and classifies without an Activity");
  h=new MainHost(this);h.open();h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{}");
  check(record("000-classify-business").getJSONArray("wikiDomains").getString(0).equals("商业与管理"),"Entrepreneurship example leaves other topics");check(record("000-classify-code").getJSONArray("wikiDomains").getString(0).equals("AI 与技术"),"Programming example becomes technical learning");check(record("000-classify-sport").getJSONArray("wikiDomains").getString(0).equals("健康与生活"),"Sports example becomes health and life");
  JSONObject update=record("000-classify-business");update.put("note","补充新的笔记正文");h.call("saveRecord",new JSONObject().put("record",update).put("allowDuplicate",true));check(WikiClassificationService.needs(record("000-classify-business")),"Editing an existing record automatically invalidates old classification");
  out.putString("stream","PASS WikiClassificationTest: "+passed+" checks\n");finish(Activity.RESULT_OK,out);
 }catch(Throwable error){out.putString("stream","FAIL WikiClassificationTest after "+passed+": "+error+"\n"+android.util.Log.getStackTraceString(error));finish(Activity.RESULT_CANCELED,out);}
 finally{serverRunning=false;try{if(server!=null)server.close();}catch(Exception ignored){}getTargetContext().getSystemService(JobScheduler.class).cancel(7304);if(secure!=null){SharedPreferences.Editor restore=secure.edit();if(encrypted==null)restore.remove("settings");else restore.putString("settings",encrypted);restore.commit();}if(h!=null)for(String id:new String[]{"000-classify-business","000-classify-code","000-classify-sport"})try{h.call("deleteRecord",new JSONObject().put("id",id));}catch(Exception ignored){}}
 }
}
